mapper.select:
SELECT id, item_code, initiation_id, standard_id, project_type, project_level, delivery_name, delivery_category, stage, required, planned_submit_date, actual_submit_date, accepted_date, submitter_id, submitter_name, reviewer_id, reviewer_name, review_comment, status, tr_required, tr_completed, file_ids, remark, tenant_id, provider_trace_id, created_by, created_at, updated_by, updated_at, deleted
FROM pmis_execution_delivery_item
WHERE initiation_id = #{initiationId}

      AND stage = #{stage}

  AND deleted = 0
ORDER BY id

SELECT COUNT(1) FROM pmis_execution_delivery_item
WHERE initiation_id = #{initiationId} AND stage = #{stage}
  AND status IN ('ACCEPTED','WAIVED') AND deleted = 0

SELECT COUNT(1) FROM pmis_execution_delivery_item
WHERE initiation_id = #{initiationId} AND stage = #{stage}
  AND required = 1 AND deleted = 0
